148:  for(const b of bots){
149:   if(!b.alive)continue;
150:   const options=attendees.filter(v=>v.id!==b.id);
151:   if(!options.length)continue;
152:   const suspectChance=playerTarget.role==='impostor'?.72:.22;
153:   const chance=Math.min(.92,suspectChance+(b.accusation>0?.15:0));
154:   let choice;
155:   if(Math.random()<chance)choice=playerTarget;
156:   else{const alternatives=options.filter(v=>v.id!==playerTarget.id);choice=alternatives.length?alternatives[Math.floor(Math.random()*alternatives.length)]:playerTarget;}
157:   tally.set(choice.id,(tally.get(choice.id)||0)+1);
158:  }
159:  const high=Math.max(...tally.values());
160:  const leaders=attendees.filter(v=>tally.get(v.id)===high);
161:  $('meeting-screen').classList.remove('visible');
